wb-status.sourceCode:
// Splits the executor's JSON status (/g1_wb/status, 5 Hz) into fields for the Indicator and Plot panels.
import { Input } from "./types";

export const inputs = ["/g1_wb/status"];
export const output = "/studio_script/wb_status";

type Output = {
  mode: string;
  rope: string;
  obstacles: string;
  scene: string;
  goal: string;
  reason: string;
  policy_wait: string;
  step_ms: number;
  latency_ms: number;
  overruns: number;
  fields_age_s: number;
  field_solve_s: number;
  field_error: string;
  goal_dist_m: number;
  waypoint: number;
  latch: number;
  reached: boolean;
  hold: boolean;
  active_allowed: boolean;
};

const num = (v: unknown): number => (typeof v === "number" ? v : NaN);

export default function script(event: Input<"/g1_wb/status">): Output | undefined {
  let s: Record<string, unknown>;
  try {
    s = JSON.parse(event.message.data);
  } catch {
    return undefined;
  }
  const mode = String(s.mode ?? "?");
  const wait = s.policy_wait == null ? "" : String(s.policy_wait);
  const xy = s.pelvis_xy as number[] | null;
  const fg = s.field_goal as number[] | null;
  const g = s.goal_xy as number[] | null;
  // the gantry procedure: slacken the rope only once the policy itself stands still (training stop latch at 0)
  let rope = "motors off";
  if (mode === "STAND_UP" || mode === "STAND") rope = "KEEP ROPE: stiff stand";
  else if (mode === "POLICY" && wait !== "") rope = "KEEP ROPE: policy waiting";
  else if (mode === "POLICY" && s.hold) rope = s.latch === 0 ? "standing: rope may slacken" : "KEEP ROPE: settling";
  else if (mode === "POLICY") rope = "walking";
  else if (mode === "DAMP") rope = "DAMP";
  return {
    mode, rope, obstacles: String(s.obstacles ?? "?"), scene: String(s.scene ?? "?"),
    goal: g ? `(${g[0].toFixed(2)}, ${g[1].toFixed(2)})` : "scene goal",
    reason: String(s.reason ?? ""), policy_wait: wait,
    step_ms: num(s.step_ms), latency_ms: num(s.latency_ms), overruns: num(s.overruns),
    fields_age_s: num(s.fields_age_s), field_solve_s: num(s.field_solve_s),
    field_error: s.field_error == null ? "" : String(s.field_error),
    goal_dist_m: xy && fg ? Math.hypot(xy[0] - fg[0], xy[1] - fg[1]) : NaN,
    waypoint: num(s.waypoint), latch: num(s.latch), reached: Boolean(s.reached), hold: Boolean(s.hold),
    active_allowed: Boolean(s.active_allowed),
  };
}

esdf-slice.sourceCode:
// The policy's ESDF at the height of the "esdf_z" slider: cuts the executor's whole window (/g1_wb/esdf_cube, mono8,
// 2 Hz) into one layer. Odometry (50 Hz) only wakes the script, so the slice follows the slider at once.
import { Input } from "./types";
import { PointCloud } from "@foxglove/schemas";

export const inputs = ["/g1_wb/esdf_cube", "/g1_slam/odometry"];
export const output = "/studio_script/esdf_slice";

type Cube = { q: Uint8Array; nx: number; ny: number; nz: number; o: number[]; dx: number; lo: number; hi: number; seq: number; stamp: any };
let cube: Cube | undefined;
let shown = "";
let seq = 0;
const cache = new Map<number, Uint8Array>();
let cacheSeq = -1;

function b64(s: string): Uint8Array {
  const A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const clean = s.replace(/[^A-Za-z0-9+/]/g, "");
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let acc = 0, bits = 0, p = 0;
  for (let i = 0; i < clean.length; i++) {
    acc = (acc << 6) | A.indexOf(clean[i]!);
    bits += 6;
    if (bits >= 8) { bits -= 8; out[p++] = (acc >> bits) & 255; }
  }
  return out;
}

function bytes(d: any): Uint8Array {
  if (d instanceof Uint8Array) return d;
  if (d && d.buffer instanceof ArrayBuffer && typeof d.length === "number") return new Uint8Array(d.buffer, d.byteOffset ?? 0, d.length);
  if (typeof d === "string") return b64(d);
  return Uint8Array.from(d as number[]);
}

export default function script(event: Input<"/g1_wb/esdf_cube"> | Input<"/g1_slam/odometry">, globalVars: any): PointCloud | undefined {
  if (event.topic === "/g1_wb/esdf_cube") {
    const m: any = event.message;
    const f = String(m.header.frame_id).split(" ");
    if (f[0] !== "esdf") return undefined;
    const nz = Number(f[5]);
    cube = { q: bytes(m.data), nx: m.height / nz, ny: m.width, nz, o: [Number(f[1]), Number(f[2]), Number(f[3])], dx: Number(f[4]),
             lo: Number(f[6]), hi: Number(f[7]), seq: ++seq, stamp: { sec: event.receiveTime.sec, nsec: event.receiveTime.nsec } };
  }
  if (!cube) return undefined;
  const z = Number(globalVars?.esdf_z ?? 0.75);
  const k = Math.max(0, Math.min(cube.nz - 1, Math.round((z - cube.o[2]) / cube.dx)));
  const key = `${k} ${cube.seq}`;
  if (key === shown) return undefined;
  shown = key;
  const { nx, ny, dx, o, lo, hi } = cube;
  if (cacheSeq !== cube.seq) { cache.clear(); cacheSeq = cube.seq; }
  let data = cache.get(k);
  if (!data) {
    const n = nx * ny, base = k * n, scale = (hi - lo) / 255;
    data = new Uint8Array(16 * n);
    const v = new DataView(data.buffer);
    for (let i = 0; i < nx; i++) {
      for (let j = 0; j < ny; j++) {
        const p = i * ny + j, b = 16 * p;
        v.setFloat32(b, o[0] + i * dx, true);
        v.setFloat32(b + 4, o[1] + j * dx, true);
        v.setFloat32(b + 8, o[2] + k * dx, true);
        v.setFloat32(b + 12, lo + cube.q[base + p] * scale, true);
      }
    }
    cache.set(k, data);
  }
  return {
    timestamp: cube.stamp, frame_id: "map",
    pose: { position: { x: 0, y: 0, z: 0 }, orientation: { x: 0, y: 0, z: 0, w: 1 } },
    point_stride: 16,
    fields: [{ name: "x", offset: 0, type: 7 }, { name: "y", offset: 4, type: 7 }, { name: "z", offset: 8, type: 7 }, { name: "sdf", offset: 12, type: 7 }],
    data,
  };
}
